/**
 * The design's coverage map (design-reference/sentral/project/coverage-data.js, window.SA_COVERAGE), copied
 * verbatim as data so the Coverage screen renders it without loading the design file at run time, and the
 * status of every feature in the gap analysis (docs/crm-enrichment/05-GAP-FEATURES.md, the Status column of
 * the feature tables, judged against the repository on 6 October 2026 before phase B). Generated once; when
 * either source changes, regenerate it rather than editing by hand.
 */
export type CoverageFeature = { id: string; n: string; m: string; r: string; d?: string; ru?: string; a?: string }
export type CoverageFlow = { id: string; n: string; s: string[]; h?: string }
export type GapStatus = "implemented" | "partial" | "missing" | "conflict" | "unknown"

export const COVERAGE: { mods: Record<string, string>; feats: CoverageFeature[]; flows: CoverageFlow[] } = {"mods":{"PIP":"Pipeline and deals","ACT":"Activities","CRM":"CRM records","CUS":"Customization","LEA":"Leads","COM":"Email and communications","AUT":"Automation","INS":"Insights and reports","PRO":"Prospecting","AIA":"AI assistant","MTG":"Meeting intelligence","MCP":"AI connector","CMP":"Email marketing","PRJ":"Projects","LGN":"Lead generation","WEB":"Web visitors","DOC":"Documents and e-sign","SEC":"Security and permissions","INT":"Integrations and API","MOB":"Mobile app","ENT":"Plans and entitlements"},"feats":[{"id":"PIP-01","n":"Kanban pipeline view","m":"PIP","r":"deals","d":"Deals appear as cards in stage columns. Dragging a card changes its stage. Each column header shows the deal count and the summed value. Cards show title, organization, owner, value, labels and an activity-status icon (planned, overdue, none)","ru":"The move is saved optimistically and rolled back on failure. Every stage change writes a changelog entry and emits `deal.stage_changed`. Cards load in pages per stage. Visibility rules apply","a":"Dragging a card updates the stage, both column totals and the history. A user without edit rights cannot drop a card"},{"id":"PIP-02","n":"Pipelines and stages","m":"PIP","r":"deals","d":"Unlimited pipelines, each with ordered stages. A stage has a name, a win probability and an optional rotting threshold. Stages can be added, renamed, reordered and deleted","ru":"Deleting a stage requires a target stage for its deals. Probability is 0–100. A pipeline can be limited to visibility groups","a":"Deals in a deleted stage land in the chosen stage. A reorder shows for every user"},{"id":"PIP-03","n":"Deal record","m":"PIP","r":"deals","d":"Title, value, currency, pipeline, stage, owner, primary person, organization, expected close date, probability, labels, source, status (open, won, lost) and custom fields","ru":"One primary person and one organization per deal; more people attach as participants (PIP-08). Value can be derived from attached products (CRM-07)","a":"A deal can be created with a title only. Every later change is in the history"},{"id":"PIP-04","n":"Deal detail view","m":"PIP","r":"deals","d":"Header with owner, followers and Won / Lost buttons. Stage progress bar. Left sidebar with summary, details, person, organization and participants. Tabs for notes, activity, call, email, files, documents and invoice. A Focus list of upcoming items and a History list filterable by notes, activities, emails, files, documents, invoices, engagement and changelog","ru":"Sidebar sections can be reordered and hidden. History is paginated. A changelog entry holds field, old value, new value, user, time and source (user, automation, API, import)","a":"A field edited anywhere appears in the changelog with before and after values"},{"id":"PIP-05","n":"Deal rotting","m":"PIP","r":"deals","d":"A deal with no activity for longer than its stage's threshold is flagged: the card turns red with the idle day count and the owner is notified","ru":"The idle clock resets on a stage move, a completed activity, an email or a note. The threshold is set per stage and is optional","a":"A deal idle beyond the threshold shows the flag; any qualifying action clears it"},{"id":"PIP-06","n":"Deal labels","m":"PIP","r":"deals","d":"Color-coded labels, several per deal, shown on cards, list rows and the detail view, and usable in filters","ru":"Label management needs a settings permission. Deleting a label removes it from all deals","a":"A label filter returns exactly the deals carrying that label"},{"id":"PIP-07","n":"Won, lost and lost reasons","m":"PIP","r":"deals","d":"A deal is closed as won or lost. Lost asks for a reason: free text, or a choice from a predefined list. An optional comment is saved as a note","ru":"Admins manage the predefined list and can make a reason mandatory. Reopening a deal clears the status and keeps the history","a":"A lost deal carries its reason, and the reason is a reporting dimension"},{"id":"PIP-08","n":"Participants","m":"PIP","r":"deals","d":"Extra people linked to a deal beyond the primary contact. They are suggested when scheduling or emailing, can be added from an email's recipients and can be bulk imported","ru":"A participant is not the primary person. Deleting a person removes the participation","a":"The email composer suggests every participant of the open deal"},{"id":"PIP-09","n":"Followers","m":"PIP","r":"deals","d":"A user can follow a deal, person, organization, product or another user to see the item and get change notifications","ru":"Following grants visibility and notifications only, never edit rights","a":"A follower is notified when the followed deal changes stage"},{"id":"PIP-10","n":"List view","m":"PIP","r":"deals","d":"Table of deals with selectable columns, multi-column sort, inline edit, bulk edit, bulk delete and export to CSV or XLSX. Every record has a system ID that can be shown and used to address it","ru":"Admins can set default columns for everyone. Bulk actions need the bulk-edit permission. Exports respect visibility","a":"A bulk edit writes one changelog entry per changed deal"},{"id":"PIP-11","n":"Forecast view","m":"PIP","r":"deals","d":"Deals in date columns by expected close date or a chosen custom date field. Each column shows open value, won value and the projected total. Dragging a card changes its date","ru":"Columns by week, month or quarter. Filters for pipeline and owner. Cards show a stage progress bar","a":"Column totals equal the sum of the cards in the column"},{"id":"PIP-12","n":"Filters","m":"PIP","r":"deals","d":"A global search finds any record by name, email, phone or field value. Quick filters (owner, label, status) plus advanced filters built from condition groups joined by ALL and ANY. Filters are saved with a name, a visibility (private or shared) and a favorite flag","ru":"Available on leads, deals, people, organizations, activities, projects and products. Conditions cover standard and custom fields with operators that fit the field type. How filters are listed and displayed is configurable","a":"A saved filter returns the same set in pipeline, list and forecast views"},{"id":"PIP-13","n":"Archive","m":"PIP","r":"deals","d":"Leads and deals can be archived to leave active views while keeping their history, and unarchived later","ru":"Archived items do not count toward the capacity limit (ENT-02) and are left out of default views","a":"An archived deal leaves the pipeline and stays findable in the archive view"},{"id":"PIP-14","n":"Deal card customization","m":"PIP","r":"deals","d":"The fields shown on pipeline cards are configurable","ru":"Set per pipeline","a":"Chosen fields render on every card of that pipeline"},{"id":"PIP-15","n":"Closed deals toggle and stage timing","m":"PIP","r":"deals","d":"A toggle shows won and lost deals in pipeline and list views. The progress bar shows each stage name with days spent","ru":"The toggle is remembered per user. Days in stage come from the stage history","a":"Days in stage equal the time between entering and leaving the stage"},{"id":"PIP-16","n":"Capacity and waitlist","m":"PIP","r":"deals","d":"When the account's lead-and-deal capacity is used up, manual adds are blocked and deals created by automations, the API, chatbot, forms or imports go to a waitlist","ru":"The waitlist can be filtered by source and bulk-added once capacity frees up. All of this applies only when a capacity limit is set; by default there is none","a":"No payload is lost when the limit is hit"},{"id":"PIP-17","n":"Duplicate and restore","m":"PIP","r":"deals","d":"A deal can be duplicated with its fields and products. A deleted deal can be restored for 30 days (CRM-12)","ru":"Duplication does not copy history or emails","a":"A restored deal returns to the stage it was deleted from"},{"id":"ACT-01","n":"Activities","m":"ACT","r":"activities","d":"An activity has a type (call, meeting, task, deadline, email, lunch), subject, date, time, duration, owner, note, a done flag and a link to a deal, lead, person, organization or project","ru":"An activity links to one deal. Completing it stamps time and user and can trigger automations. Activities created by a workflow are marked as such","a":"A completed activity shows in the linked record's history"},{"id":"ACT-02","n":"Custom activity types and fields","m":"ACT","r":"activities","d":"Admins add, rename, order and deactivate activity types and add custom fields to capture outcomes","ru":"A deactivated type stays on past activities and is hidden for new ones","a":"A new type is selectable immediately and reportable"},{"id":"ACT-03","n":"Calendar and list views","m":"ACT","r":"activities","d":"Day, week and month calendar and a to-do list, filterable by user, type and status. Drag to reschedule","ru":"Managers see team members' activities within visibility rules. Project tasks can be shown beside sales activities","a":"Rescheduling in the calendar updates the activity and any synced calendar event"},{"id":"ACT-04","n":"Reminders","m":"ACT","r":"activities","d":"Reminders in the app, by email, by desktop notification and by push, in any combination per user","ru":"Timing configurable per user. A daily summary is optional. The notification center also carries productivity tips, as in the source","a":"A reminder fires once per channel at the configured time"},{"id":"ACT-05","n":"Priority labels","m":"ACT","r":"activities","d":"High, medium and low priority, editable inline or in bulk, shown in calendar and list","ru":"None stated.","a":"Priority is filterable and sortable"},{"id":"ACT-06","n":"Bulk activities","m":"ACT","r":"activities","d":"Create or edit activities for many records at once from list views or the inbox","ru":"Needs the bulk-edit permission","a":"One activity is created per selected record"},{"id":"ACT-07","n":"Next-step prompt","m":"ACT","r":"activities","d":"Marking an activity done prompts for the next one. Deals without a planned activity show a warning icon on their card","ru":"The prompt can be switched off per user","a":"A deal with no open activity shows the warning"},{"id":"ACT-08","n":"Activity invites","m":"ACT","r":"activities","d":"Adding people as guests sends them calendar invites through the synced calendar and tracks responses","ru":"Requires calendar sync (ACT-09)","a":"A guest receives an invite and the response shows on the activity"},{"id":"ACT-09","n":"Calendar sync","m":"ACT","r":"activities","d":"One- or two-way sync with Google and Microsoft calendars. The user picks the calendar and the activity types to sync. Private events sync as private","ru":"Recurring events are not created natively; recurring external events appear read-only, as in the source product","a":"An event changed on either side is updated on the other in two-way mode"},{"id":"CRM-01","n":"People and organizations","m":"CRM","r":"contacts","d":"Person: name, emails, phones, organization, owner, labels, marketing status, custom fields. Organization: name, address, owner, labels, custom fields. Each has a detail view with history, linked deals, activities, files and emails","ru":"The admin's organization and contact records stay the source of truth; this module adds columns and related tables. Contact rules are a setting, off by default (CUS-07). Survey respondents stay outside the CRM under the anonymity firewall. A person belongs to at most one organization","a":"Opening a person shows every linked deal, activity and email the user may see"},{"id":"CRM-02","n":"Contacts timeline","m":"CRM","r":"contacts","d":"One row per person or organization with activity icons along a time axis, a today marker and overdue items in red","ru":"Controls for look-back period, follow-up frequency, activity type and owner","a":"The timeline shows the same activities as the record's history"},{"id":"CRM-03","n":"Contacts map","m":"CRM","r":"contacts","d":"People and organizations plotted on a map by address, filterable by city, region and country","ru":"Addresses are geocoded once and cached. Records without a usable address are listed separately","a":"A filter by country shows only records in that country"},{"id":"CRM-04","n":"Contact sync","m":"CRM","r":"contacts","d":"Two-way sync of people with Google and Microsoft address books","ru":"The user chooses which contacts sync. Matching is by email address. New contacts follow the contact-rule setting, which is off by default","a":"A contact edited on either side is updated on the other"},{"id":"CRM-05","n":"File attachments","m":"CRM","r":"contacts","d":"Files attach to leads, deals, people, organizations, products and projects and are listed in the record's history","ru":"Stored in the admin's storage under the same visibility as the record","a":"A user who cannot see the record cannot fetch the file"},{"id":"CRM-06","n":"Notes, mentions and comments","m":"CRM","r":"contacts","d":"Rich-text notes on any record. @mention notifies a user. Comments thread under notes and other history items. Notes can be pinned","ru":"Mentions respect visibility: a user who cannot see the record is not notified with its content","a":"A mentioned user gets a notification that opens the record"},{"id":"CRM-07","n":"Product catalog","m":"CRM","r":"deals","d":"Products with name, code, unit, prices per currency, tax, price variations, notes and custom fields. Products attach to a deal with quantity, price and discount, and the deal value is calculated from them","ru":"Default tax mode (inclusive, exclusive, none) is set per user. Products import from a spreadsheet","a":"Changing a product line recalculates the deal value"},{"id":"CRM-08","n":"Subscriptions and installments","m":"CRM","r":"deals","d":"A product on a deal can be recurring (billing frequency, renew until canceled or a fixed number of cycles, up to 208) or split into installments. The system computes MRR, ARR, ACV and TCV","ru":"Recurring products calculate all four values; installments calculate ACV and TCV. For Orgpuls's own subscriptions the figures come from the billing mirror, not from product lines","a":"The values match the configured schedule and feed forecast reports (INS-06)"},{"id":"CRM-09","n":"Import","m":"CRM","r":"contacts","d":"Spreadsheet import for all entities in one session, with column-to-field mapping, duplicate detection with a merge-or-create choice, a skip file of rejected rows and an import history","ru":"Mapping can be suggested by AI (AIA-05). Rows over the capacity limit go to the skip file. A consent source per row can be required by a setting, off by default","a":"Every source row ends up created, merged or in the skip file with a reason"},{"id":"CRM-10","n":"Export","m":"CRM","r":"contacts","d":"Export of any list view and of full data sets to CSV or XLSX","ru":"Needs the export permission. Exports are logged for security alerts (SEC-02)","a":"The export contains exactly the rows and columns visible to the user"},{"id":"CRM-11","n":"Merge duplicates","m":"CRM","r":"contacts","d":"Duplicate people and organizations are detected by matching rules that admins configure, listed for review and merged","ru":"A possible duplicate is flagged on the record's detail view. The compare view shows name, deals, activities, creation date, owner and visibility, and the user picks the surviving values. Deals, activities, emails and files move to the surviving record","a":"After a merge one record remains with the combined history"},{"id":"CRM-12","n":"Restore data","m":"CRM","r":"contacts","d":"Items deleted in the last 30 days are listed with who deleted them, when and from which source, and can be restored. Bulk changes can be reverted","ru":"Covers people, organizations, deals, products, leads and activities. Who may restore what follows permissions. Bulk deletes show a preview; second-admin approval is a setting, off by default","a":"A restored item returns with its links intact"},{"id":"CRM-13","n":"Related organizations","m":"CRM","r":"contacts","d":"Organizations link to each other as parent, daughter or related","ru":"Shown on the organization detail view","a":"A parent lists its daughters and the reverse"},{"id":"CRM-14","n":"Contact labels","m":"CRM","r":"contacts","d":"Color-coded labels on people and organizations","ru":"Separate label sets from deals and leads","a":"Labels are filterable"},{"id":"CRM-15","n":"Source fields","m":"CRM","r":"contacts","d":"Leads and deals record where they came from: manual, import, API, automation, an installed app, prospect search, lead suggestions, web form, chatbot, live chat, web visitors, campaign or messaging","ru":"Filled automatically on creation and kept through conversion and archiving","a":"Source is a reporting dimension"},{"id":"CUS-01","n":"Custom fields","m":"CUS","r":"settings","d":"16 field types on leads and deals, people, organizations, products, projects and activities: text, large text, single option, multiple options, autocomplete, numerical, monetary, user, organization, person, phone, time, time range, date, date range, address. Fields sit in groups and can be shown in add forms and detail views","ru":"Up to 1,000 options per option field. Field count per company is an entitlement","a":"A new field appears in forms, filters, reports, import and the API without a deploy"},{"id":"CUS-02","n":"Field quality rules","m":"CUS","r":"settings","d":"A field can be marked important (a nudge) or required (blocks saving), optionally only from a given stage. A description, shown behind an info icon, explains how to fill it","ru":"Required rules apply to manual edits and are reported, not enforced, on API and import","a":"A deal cannot move to a stage whose required fields are empty"},{"id":"CUS-03","n":"Pipeline-specific and read-only fields","m":"CUS","r":"settings","d":"A field can be shown only in chosen pipelines. A field can be read-only for chosen users or hidden from them","ru":"Enforced in the database, not only in the interface","a":"A user without access cannot read the field through any channel"},{"id":"CUS-04","n":"Formula fields","m":"CUS","r":"settings","d":"Numeric and monetary deal fields can be calculated from other fields","ru":"Recalculated when an input changes. A formula cannot reference itself","a":"The stored value always equals the formula result"},{"id":"CUS-05","n":"Languages and locale","m":"CUS","r":"settings","d":"Interface language, date and number format and time zone per user, from a translation catalog","ru":"English is the default, as decided in the admin specification; further languages are added through the catalog","a":"Switching language changes every label without a reload of data"},{"id":"CUS-06","n":"Currencies","m":"CUS","r":"settings","d":"Deals and products in any major currency plus custom currencies, with a company default","ru":"Conversion uses stored exchange rates at report time","a":"A report in the default currency converts all deal values"},{"id":"CUS-07","n":"Module switches and rule settings","m":"CUS","r":"settings","d":"Admins turn whole modules on or off and manage every rule that can restrict a feature: contact rules, consent checks, tracking, approvals, limits and plan gates. The settings table below lists them","ru":"A switched-off module disappears from navigation and its API returns a disabled error. Every rule defaults to unrestricted, so each feature works in full from the start. Changes to settings are logged","a":"Turning Products off hides it for every user. With default settings no feature is blocked by a rule"},{"id":"CUS-08","n":"Sandbox","m":"CUS","r":"settings","d":"A separate test company for trying configuration and automations. A new setup can start with sample records, marked as samples and removable in one step, as in the source","ru":"In the Orgpuls admin this is the seeded demo tenant. It holds configuration and demo data, never customer data","a":"Changes in the sandbox never touch the live company"},{"id":"LEA-01","n":"Leads inbox","m":"LEA","r":"contacts","d":"A list of leads with title, person or organization, value, labels, owner, source and next activity, with sortable columns, filters and an archive toggle","ru":"A lead must link to a person or an organization. Leads share custom fields with deals","a":"A lead never appears in a pipeline before conversion"},{"id":"LEA-02","n":"Lead labels","m":"LEA","r":"contacts","d":"Color-coded labels such as hot, warm and cold, several per lead, with bulk edit","ru":"Label sets are editable by users with the settings permission","a":"The label filter returns leads carrying that label"},{"id":"LEA-03","n":"Convert lead and deal","m":"LEA","r":"contacts","d":"A lead converts to a deal in a chosen pipeline and stage. A deal can convert back to a lead","ru":"Notes, activities, emails and files follow the record in both directions","a":"The converted deal shows the lead's full history"},{"id":"LEA-04","n":"Lead creation and import","m":"LEA","r":"contacts","d":"Leads are created manually, by import, the API, web forms, chatbot, live chat, prospect search and web visitors","ru":"Each sets the source field (CRM-15)","a":"Every channel produces a lead with the right source"},{"id":"LEA-05","n":"Lead email","m":"LEA","r":"contacts","d":"Emails are sent and received on a lead and stay linked after conversion","ru":"Uses email sync or the BCC drop-box (COM-01, COM-02)","a":"A reply to a lead email appears on the lead"},{"id":"LEA-06","n":"Messaging inbox and social connector","m":"LEA","r":"inbox","d":"A shared inbox for conversations from connected messaging channels, each linked to a lead or contact, and a LinkedIn connector listed beside it","ru":"The source shows both only in a screenshot. The inbox follows COM-13; the LinkedIn connector's functions must be defined before its phase","a":"A message from a connected channel appears in the inbox and can be turned into a lead"},{"id":"COM-01","n":"BCC drop-box","m":"COM","r":"inbox","d":"Every user has a private address. Mail sent or forwarded to it is stored and linked to the matching person and their open deal. A deal-specific address links to that deal. Alternative sender addresses can be registered so that mail forwarded from them is accepted","ru":"Works without mailbox sync. Unmatched mail goes to an unlinked list for manual linking","a":"A BCC'd email appears on the person and deal"},{"id":"COM-02","n":"Two-way email sync and inbox","m":"COM","r":"inbox","d":"Users connect Gmail, Microsoft 365, Exchange or any IMAP mailbox and then read, send and reply inside the CRM. Conversations link to deals, leads and projects automatically by participant, or manually","ru":"Per-conversation visibility: private or shared. The user picks folders, a sync start date and a sender alias. Sent emails are logged as activities at send time. Tokens are stored encrypted","a":"Mail sent from either the CRM or the mail client appears in both"},{"id":"COM-03","n":"Multiple mailboxes","m":"COM","r":"inbox","d":"A user syncs several accounts into one inbox and chooses the sender per email","ru":"The number of accounts per user is an entitlement","a":"Each email records which account sent it"},{"id":"COM-04","n":"Team inbox","m":"COM","r":"inbox","d":"A shared mailbox that several users read and answer","ru":"Settings for who can view and reply, default visibility, sync start and folders. The number of team inboxes is an entitlement","a":"A reply by one user is visible to the others on the thread"},{"id":"COM-05","n":"Templates, signatures and merge fields","m":"COM","r":"inbox","d":"Reusable templates, private or shared, including ready-made starter templates, with merge fields for deal, person, organization and user, personalized hyperlinks and a signature per account","ru":"A missing merge value is flagged before sending","a":"A template renders with the recipient's data"},{"id":"COM-06","n":"Open and click tracking","m":"COM","r":"inbox","d":"Tracks opens and link clicks and notifies the sender in real time","ru":"Can be switched off per email. Opens are unreliable where mail clients prefetch images, so reports must say so. Tracking is on by default and can be switched off in settings (CUS-07)","a":"An opened email shows an open event with time"},{"id":"COM-07","n":"Group emailing","m":"COM","r":"inbox","d":"One email sent individually to many selected recipients from list views or the contacts timeline, using a template","ru":"The source product caps a send at 100 recipients. Needs sync and the bulk-edit permission. Consent and suppression checks are a setting, off by default (CUS-07)","a":"Each recipient gets a personal copy linked to their record"},{"id":"COM-08","n":"Email scheduling and outbox","m":"COM","r":"inbox","d":"An email can be scheduled for later. Failed sends show the provider's reason and can be retried","ru":"Scheduled mail can be edited or canceled until sent","a":"A scheduled email leaves at the set time or shows a failure reason"},{"id":"COM-09","n":"Labels, archiving and warnings","m":"COM","r":"inbox","d":"Email labels for sorting, two-way archive state with Gmail, thread status at a glance and a warning when an attachment is mentioned but missing","ru":"None stated.","a":"Archiving a thread in either place archives it in both"},{"id":"COM-10","n":"Meeting scheduler","m":"COM","r":"activities","d":"A booking page built from the user's availability. Two link types: general availability and specific proposed times. The contact picks a slot; both get a confirmation and a linked activity is created","ru":"Duration, working hours, time zone handling and extra questions are configurable. Booked slots disappear at once. Links can sit in signatures, templates and automated emails","a":"A booked meeting appears on the calendar and on the record"},{"id":"COM-11","n":"Video call links","m":"COM","r":"activities","d":"A video link is created automatically for a scheduled meeting","ru":"Zoom, Microsoft Teams and Google Meet through adapters","a":"The invite contains a working link"},{"id":"COM-12","n":"Calling","m":"COM","r":"inbox","d":"Click-to-call through a telephony provider adapter, with one provider set as the default calling app. Calls are logged as activities with outcome, duration and recording link. A call started on the web can continue on the user's phone. Incoming callers are matched to contacts","ru":"No dialer is built; providers supply calling, recording and SMS","a":"A finished call appears as a completed activity on the right record"},{"id":"COM-13","n":"Messaging","m":"COM","r":"inbox","d":"WhatsApp Business conversations in the inbox, linked to deals and contacts, with approved templates, quick replies, labels, delivery and read status, emoji reactions, inline images and audio, attachments and notifications","ru":"The messaging provider charges per conversation. Automation of messages follows later, as in the source","a":"A reply from a contact appears in the thread and notifies the owner"},{"id":"COM-14","n":"Mail client add-ons","m":"COM","r":"inbox","d":"A Gmail side panel and a browser extension to view and add contacts, deals, notes and activities without leaving the mailbox","ru":"None stated.","a":"A deal created in the add-on appears in the pipeline"},{"id":"AUT-01","n":"Workflow builder","m":"AUT","r":"automation","d":"A canvas where a workflow is built from a trigger, conditions and steps. Workflows have a name, description, owner and a draft or active state","ru":"Steps can be copied and pasted. The number of active workflows per company is an entitlement","a":"An active workflow runs on the next matching event"},{"id":"AUT-02","n":"Event triggers","m":"AUT","r":"automation","d":"A workflow starts when a deal, person, activity, lead, organization or project is added, updated or deleted","ru":"Update triggers can require a specific field change. Changes made by a workflow can trigger other workflows, within loop limits","a":"Each of the 18 entity-event pairs can start a workflow"},{"id":"AUT-03","n":"Date triggers","m":"AUT","r":"automation","d":"A workflow starts on, before or after a date field of a deal, person, activity or organization","ru":"Evaluated on a schedule against the field's value at run time","a":"A workflow set to 30 days before a renewal date fires on that day"},{"id":"AUT-04","n":"Conditions","m":"AUT","r":"automation","d":"Filters on the trigger record and its related records, combined with AND and OR. Email conditions test whether a sent email was opened or answered","ru":"Conditions are checked when the trigger fires and again where a step says so. The builder suggests common conditions, and custom ones can be written","a":"A record that fails the conditions starts no run"},{"id":"AUT-05","n":"Delay and wait-for","m":"AUT","r":"automation","d":"A delay pauses a path for a duration or until a date and can skip weekends. A wait-for step pauses until a condition is met","ru":"Up to 10 delay steps and 90 days in total per path; skipped weekends still count toward the 90 days. A wait-for step gives up after 7 days and stops the run","a":"A run resumes at the right time or ends with a stated reason"},{"id":"AUT-06","n":"If/else branches","m":"AUT","r":"automation","d":"A step splits the workflow into paths by condition","ru":"The number of branches per workflow is an entitlement","a":"Each run follows exactly one path per branch"},{"id":"AUT-07","n":"Actions","m":"AUT","r":"automation","d":"Create, update or delete a person, organization, lead, deal or activity. Send an email from a template. Add a note. Run campaign and project actions. Call a webhook with POST, PUT or DELETE and a key-value or raw JSON body. Post to Slack or Microsoft Teams. Create an Asana or Trello task","ru":"Up to 10 actions per path. Field values can come from the trigger record. An email template can be previewed before it is used. Emails send from the chosen sender's synced mailbox. Consent and suppression checks on automated email are a setting, off by default (CUS-07)","a":"Every action type completes or reports an error in the run history"},{"id":"AUT-08","n":"Workflow templates","m":"AUT","r":"automation","d":"A library of ready-made workflows grouped by purpose. Choosing one opens a short setup and saves a draft","ru":"The source ships 36; the starting set is a product decision","a":"A template becomes an editable workflow"},{"id":"AUT-09","n":"Monitoring and limits","m":"AUT","r":"automation","d":"A history of every run with each step's result. An overview shows most failed, most active and never-run workflows and a health trend for today, 7 and 14 days. Owners are alerted on failure","ru":"Loop protection caps runs in a rolling 10-minute window; the source's values are 10,000 per company and 5,000 per workflow. The history of a webhook step shows the final request body and path","a":"A failing step shows its error and links to the step"},{"id":"AUT-10","n":"Ownership and sharing","m":"AUT","r":"automation","d":"A workflow runs with its owner's permissions. Owners share it, activate it for selected users or a whole team and transfer ownership. Global admins can edit any workflow","ru":"Creating workflows needs a permission that only admins have by default. Deactivating a user who owns active workflows prompts a transfer. The list can be filtered by owned by me and owned by others, and a transfer notifies both users","a":"A transferred workflow keeps running under the new owner"},{"id":"AUT-11","n":"Automatic assignment","m":"AUT","r":"automation","d":"Rules assign an owner when a lead is added or a deal is added or updated. A rule has conditions and an assignee: a user, a team in round-robin, the organization's owner or the person's owner","ru":"Rules are evaluated in priority order; the first match wins. The deal-updated event means a change of pipeline or stage. Conditions can use deal, lead, person and organization fields. A history lists every evaluation","a":"A new lead matching a team rule goes to the next member in rotation"},{"id":"AUT-12","n":"Sequences","m":"AUT","r":"automation","d":"A linear flow, built on a drag-and-drop canvas, of email steps (sent automatically or queued for manual sending) and activity steps, with delays that can skip weekends. Leads or deals are enrolled one by one, in bulk or by a workflow","ru":"Enrollment ends on reply, on a stage change or manually, one by one or in bulk. Steps can be skipped or the sequence stopped. Emails carry the sender's signature automatically. The number of sequences is an entitlement. Consent and suppression checks are a setting, off by default (CUS-07)","a":"Each enrolled record shows its current step and status: in progress, completed or failed"},{"id":"INS-01","n":"Report builder and types","m":"INS","r":"insights","d":"Reports on deals (performance, conversion, duration, progress, products), activities (performance, emails), leads (performance, conversion), contacts (people, organizations), campaigns (performance, conversion), projects (performance, duration) and revenue forecast (deal, product). A report has a measure, a view-by dimension, an optional segment-by dimension, filters and a period. Measures include count, value, weighted value, average value, conversion rate and time to win; the source combines deal count, average value, close rate and time to win into sales velocity. Filters include does-not-contain","ru":"Campaign and project reports need those modules. A user only sees data their visibility allows. Business figures reuse the admin's SQL views, so each metric has one definition","a":"Each of the 17 report types returns figures that match the underlying list view"},{"id":"INS-02","n":"Charts","m":"INS","r":"insights","d":"Column, bar, pie, scorecard and table. Colors are editable. A scorecard shows the change against the previous period. Table columns are configurable and sortable","ru":"Pie charts have no view-by dimension","a":"Switching chart type keeps the data and filters"},{"id":"INS-03","n":"Dashboards","m":"INS","r":"insights","d":"Reports are placed on a grid, moved and resized. One default dashboard, custom dashboards and role-based templates for reps and managers. Reports, goals and dashboards can be duplicated, and a report shared by someone else can be copied into the user's own","ru":"Custom dashboards are an entitlement. Period and user filters apply to the whole dashboard","a":"A dashboard reopens exactly as arranged"},{"id":"INS-04","n":"Sharing and collaboration","m":"INS","r":"insights","d":"Reports and dashboards are shared with users as viewer or editor, and by a public live link for people without an account","ru":"A public link can be revoked. Link viewers see the owner's data scope","a":"A revoked link stops working at once"},{"id":"INS-05","n":"Goals","m":"INS","r":"insights","d":"Goals on deals (added, progressed, won), activities (added, completed) and forecast (weighted revenue). A goal has an assignee (user, team or company), pipeline, frequency (weekly to yearly), duration and a count or value target","ru":"Team goals need teams (SEC-09). Stage goals also show in the pipeline view","a":"Progress equals the count or value of matching records in the period"},{"id":"INS-06","n":"Forecast reports","m":"INS","r":"insights","d":"Deal revenue forecast from values and expected close dates, and product revenue forecast from recurring products and installments","ru":"Weighted by stage probability on request","a":"Forecast totals reconcile with the forecast view (PIP-11)"},{"id":"INS-07","n":"Custom-field reporting","m":"INS","r":"insights","d":"Custom fields are available as dimensions, filters and measures, including averages of numeric and monetary fields. One field can carry several filter conditions","ru":"An entitlement in the source product","a":"A new custom field is reportable without configuration"},{"id":"INS-08","n":"Export","m":"INS","r":"insights","d":"Charts export as PNG or PDF, data as CSV or XLSX. Clicking a chart segment opens and exports its underlying rows","ru":"Follows the export permission","a":"Exported rows equal the rows behind the chart"},{"id":"INS-09","n":"AI report generation","m":"INS","r":"insights","d":"A typed request produces a report definition the user can then edit. Ready-made prompts are offered, and the request can be refined in a chat. Custom fields can be named in the request","ru":"The model returns a definition, never raw numbers; the engine computes the figures","a":"A generated report is a normal report that passes the same checks as INS-01"},{"id":"INS-10","n":"Capacity and freshness","m":"INS","r":"insights","d":"Reports read live data. The number of reports per user is an entitlement","ru":"Heavy aggregations use rollup tables refreshed by events","a":"A change to a deal shows in reports without manual refresh"},{"id":"PRO-01","n":"Feed","m":"PRO","r":"feed","d":"A workspace of next-best steps on the user's open deals in three tabs. Follow-ups: email replies, no reply after 5 days, today's planned activities, emails opened, links clicked, sequence emails waiting to send. Overlooked deals: no follow-up activity, overdue activities. Opportunities: new deals with no activity","ru":"Scope is set once: all pipelines and stages or chosen ones. Cards are generated from events, not polled","a":"Each card type appears when its condition is met and leaves when resolved"},{"id":"PRO-02","n":"Feed actions","m":"PRO","r":"feed","d":"A card offers quick actions (schedule a task, send an email, open the deal) and opens a side panel with the deal, its activities and contacts. A counter shows items done today","ru":"Filters by pipeline stage, card type and score","a":"Completing the action removes the card and advances the counter"},{"id":"PRO-03","n":"Scoring models","m":"PRO","r":"feed","d":"A score from 0 to 100 per deal from criteria in three groups: highly positive (+25), slightly positive (+10), negative (−10), with AND/OR conditions. A preview shows which criteria matched","ru":"A model targets deals in one pipeline and only one model is active per pipeline. The number of models is an entitlement. The admin's health score and product events can be criteria","a":"A deal's score changes when a field used by a criterion changes"},{"id":"PRO-04","n":"Company enrichment","m":"PRO","r":"feed","d":"Fills empty organization fields: address, industry, employee count, annual revenue, LinkedIn profile, website","ru":"Never overwrites existing values. Default enrichment fields can be hidden. Uses a data provider or a public company register through an adapter. Consumes credits","a":"Enrichment writes only empty fields and logs the source"},{"id":"PRO-05","n":"Person enrichment","m":"PRO","r":"feed","d":"Finds a person's email address and phone number from name, organization and LinkedIn profile","ru":"Built in full. New contact data follows the contact-rule setting, off by default. Consumes credits","a":"Found values are stored with source and date"},{"id":"PRO-06","n":"Bulk enrichment and credits","m":"PRO","r":"feed","d":"Up to 100 people or organizations enriched at once from a list view. A monthly credit allowance resets each billing cycle; top-ups can be bought","ru":"Where a credit allowance is set, a request with too few credits is refused before any call to the provider","a":"Credits used equal records enriched"},{"id":"PRO-07","n":"Reverse lookup","m":"PRO","r":"feed","d":"For an email from an unknown sender, proposes a new person and organization with enriched fields","ru":"Uses PRO-04 and PRO-05 and their limits","a":"Accepting the proposal creates linked records"},{"id":"AIA-01","n":"Assistant chat","m":"AIA","r":"assistant","d":"A chat reachable from every screen, by text or voice. It answers questions about the account's data, summarizes records, drafts notes and emails, explains how features work and keeps a history","ru":"Retrieval runs with the asking user's permissions. Answers cite the records used. Survey responses are outside its reach, and its reads of customer data are audited","a":"The assistant never returns data the user cannot open"},{"id":"AIA-02","n":"AI notifications","m":"AIA","r":"feed","d":"Cards that estimate a deal's chance of advancing, flag stalled or slipping deals and propose the next action with a one-click button. A progress panel shows the user's daily tasks, calls and activities and the month's new deals, won deals and forecast","ru":"Admins can hide AI scoring for the whole account. Estimates carry a short reason","a":"Each card links to the deal and its suggested action works"},{"id":"AIA-03","n":"Email writer","m":"AIA","r":"inbox","d":"In any composer, a prompt plus tone (professional, formal, friendly) and length (short, standard, long) produces a draft in the prompt's language","ru":"The draft is inserted for editing, never sent automatically","a":"The draft uses the linked deal and person context"},{"id":"AIA-04","n":"Email summary and replies","m":"AIA","r":"inbox","d":"For a thread: a summary, sentiment, a readiness-to-buy score from 1 to 10 with a reason, action items and suggested replies","ru":"Runs on demand per thread","a":"The summary reflects the latest message in the thread"},{"id":"AIA-05","n":"Import mapping","m":"AIA","r":"contacts","d":"Suggests which spreadsheet column maps to which field, including option fields","ru":"The user confirms before import","a":"Suggested mappings are editable and logged"},{"id":"AIA-06","n":"Integration recommendations","m":"AIA","r":"platform","d":"Suggests integrations from the catalog and answers natural-language searches over it","ru":"Works on the integration catalog (INT-11). Recommendations draw on the tools already in use and on what similar companies use","a":"Search returns catalog entries matching the described need"},{"id":"AIA-07","n":"Card scanner","m":"AIA","r":"mobile","d":"The mobile app photographs a business card and creates a contact, capturing several phones and emails","ru":"The user reviews before saving. The image is stored on the contact. The new contact follows the contact-rule setting, off by default","a":"A scanned card produces a correct, editable contact draft"},{"id":"MTG-01","n":"Pre-call brief","m":"MTG","r":"meetings","d":"Before each meeting, a brief built from deal history, past emails, earlier conversations and contact and organization data, with a checklist of what changed since the last contact","ru":"Users add free-form instructions that shape every brief. Unlinked meetings are flagged","a":"A brief exists before the meeting starts and cites its sources"},{"id":"MTG-02","n":"Notetaker bot","m":"MTG","r":"meetings","d":"A bot joins Google Meet, Zoom or Microsoft Teams from the calendar as a visible participant and records","ru":"Joins about two minutes before start. The meeting owner can remove it. Consent notices can be emailed to attendees in advance, 24 hours by default","a":"The bot joins scheduled meetings that have a link and leaves when removed"},{"id":"MTG-03","n":"Desktop capture","m":"MTG","r":"meetings","d":"A desktop app records the computer's audio with no bot in the call, covering VoIP, phone and in-person meetings","ru":"macOS and Windows clients; the source supports macOS 13 or later on Apple Silicon and 64-bit Windows 10 or later. The user controls participant notices","a":"A recording made in the desktop app appears in the same workspace"},{"id":"MTG-04","n":"Transcript and recap","m":"MTG","r":"meetings","d":"A timestamped transcript with speakers, a recap with key takeaways and next steps, saved as a note on the linked deal, person or organization","ru":"Clicking an action item jumps to that moment. A message goes to Slack when the recap is ready","a":"Recap and transcript are attached to the right record"},{"id":"MTG-05","n":"CRM update suggestions","m":"MTG","r":"meetings","d":"After the call, proposed changes to deal, person and organization fields, including custom fields, labels and new contacts, each shown beside the current value","ru":"Nothing is written until the user approves, item by item or all at once. A proposed new contact follows the contact-rule setting, off by default","a":"Approved items are written and logged with the meeting as source"},{"id":"MTG-06","n":"Transcript upload","m":"MTG","r":"meetings","d":"A transcript from a call recorded elsewhere can be uploaded to get the same recap and suggestions","ru":"None stated.","a":"An uploaded transcript produces a recap"},{"id":"MTG-07","n":"Unscheduled calls","m":"MTG","r":"meetings","d":"An ad hoc call with no calendar event can be recorded from the desktop app","ru":"No maximum duration in the source product","a":"The recording can be linked to a deal afterward"},{"id":"MTG-08","n":"Workspace and controls","m":"MTG","r":"meetings","d":"A workspace with upcoming meetings, post-meeting actions and history. On by default per user; admins switch it off per user. One permission covers all features. Its own mailbox connection reads email for briefs","ru":"Consent notices to attendees are a setting, on by default with 24 hours' notice as in the source (CUS-07). Recording law varies by country (open point 5)","a":"A user without the permission sees no meeting workspace"},{"id":"MCP-01","n":"MCP server","m":"MCP","r":"platform","d":"An MCP endpoint that assistants connect to with an OAuth login. A sync mode, as in the source's ChatGPT app, indexes records every 30 minutes so an assistant can search deals, leads, contacts, pipelines, activities, email conversations, products, users, custom fields, automations and reports","ru":"Every call runs as the connected user with that user's permissions and counts against API limits. Tools expose CRM data only, never survey data","a":"An assistant can only see and change what the user can"},{"id":"MCP-02","n":"Tool catalog","m":"MCP","r":"platform","d":"Tools to get, list, add, update and search activities, deals, people, organizations, leads, products, pipeline stages and notes, plus convert lead to deal","ru":"The source documents 37 tools. Tool names and schemas are generated from the API definitions","a":"Every tool has a schema and returns structured results"},{"id":"MCP-03","n":"Admin controls","m":"MCP","r":"platform","d":"A company-level switch for MCP access. Switching it off blocks new connections and removes existing ones","ru":"Does not affect API tokens or other integrations","a":"After switch-off no assistant call succeeds"},{"id":"CMP-01","n":"Email builder","m":"CMP","r":"marketing","d":"A drag-and-drop editor with rows for layout and content blocks: title, paragraph, list, image, button, divider, social, HTML, video, icons, menu. Row properties cover border, background color or image and padding. A design starts blank or from a layout. Desktop and mobile preview","ru":"The footer always carries the sender's postal address and an unsubscribe link and cannot be removed","a":"A built email renders in the preview as it is delivered"},{"id":"CMP-02","n":"Templates","m":"CMP","r":"marketing","d":"Ready-made layouts, a library of saved templates and code-your-own HTML templates","ru":"Templates are stored as data and versioned","a":"A template can start a new campaign"},{"id":"CMP-03","n":"Audience","m":"CMP","r":"marketing","d":"Recipients are chosen with CRM filters over people, including engagement and location. Sales and marketing share one contact list","ru":"Only addresses with the subscribed status receive mail","a":"The recipient count equals subscribed matches of the filter"},{"id":"CMP-04","n":"Marketing status and consent","m":"CMP","r":"marketing","d":"Each email address has a status: no consent, subscribed, unsubscribed, bounced, pending double opt-in, pending upgrade, archived. Single or double opt-in. Every change is logged with time and source","ru":"The admin's consent record, with its basis and date, is the source of truth, and the statuses here are derived from it. The suppression list applies to every campaign send; sales email follows the consent setting (CUS-07)","a":"An unsubscribed address cannot be mailed by any campaign"},{"id":"CMP-05","n":"Scheduling and sending","m":"CMP","r":"marketing","d":"Send now or at a set time through a sending provider on a marketing stream that is separate from transactional mail","ru":"The subscriber allowance is an entitlement; addresses over it wait as pending","a":"A scheduled campaign leaves at the set time"},{"id":"CMP-06","n":"Campaign analytics","m":"CMP","r":"marketing","d":"Per campaign: delivered, bounced, unsubscribed, spam reports, total and unique opens and clicks, open rate, click rate, click-through rate and top locations. Owners can be notified of engagement","ru":"Needs engagement tracking switched on. A hard bounce or five soft bounces set the address to bounced","a":"Figures match provider events for the campaign"},{"id":"CMP-07","n":"Automated campaigns","m":"CMP","r":"marketing","d":"A campaign email can be a step in a workflow, so CRM changes trigger marketing mail with delays","ru":"The audience comes from the workflow, not a filter","a":"A triggered email obeys consent status"},{"id":"CMP-08","n":"Deliverability","m":"CMP","r":"marketing","d":"Sender domain authentication with DNS checks, account verification before first send, compliance recommendations and list hygiene warnings","ru":"The sending provider requires an authenticated domain before the first send","a":"An unauthenticated domain cannot send"},{"id":"CMP-09","n":"Campaign insights","m":"CMP","r":"marketing","d":"Campaign performance and conversion reports in Insights, a filter by campaign type, and a comparison of two or more campaigns in one chart","ru":"The comparison is a higher tier in the source product","a":"The comparison shows the same figures as each campaign's own report"},{"id":"PRJ-01","n":"Boards and phases","m":"PRJ","r":"projects","d":"Projects sit on kanban boards and move through phases. Several boards can exist for different processes","ru":"Phases are added, renamed, reordered and deleted like pipeline stages","a":"Dragging a project changes its phase and logs it"},{"id":"PRJ-02","n":"Project record","m":"PRJ","r":"projects","d":"Title, board, phase, owner, start and end dates, labels, description, custom fields and links to deals, one person and one organization","ru":"A project can be created from a won deal, with an AI-drafted brief from the deal's emails, notes and files that the user reviews","a":"A project created from a deal shows the deal and its contacts"},{"id":"PRJ-03","n":"Work items","m":"PRJ","r":"projects","d":"Tasks (optional owner, start and due date, several assignees), subtasks under a task, milestones for key progress points and activities for scheduled events","ru":"Subtasks always have a parent. Activities need date, time and owner and can sync to a calendar","a":"Completing all subtasks does not auto-complete the parent unless set"},{"id":"PRJ-04","n":"Dependencies and timeline","m":"PRJ","r":"projects","d":"Tasks and milestones can depend on others. A Gantt timeline shows items by month with dependency lines, and a whole phase or group can be dragged to shift it","ru":"A dependency cannot form a cycle. Overdue items are highlighted","a":"Shifting a phase keeps the spacing between its items"},{"id":"PRJ-05","n":"Project templates","m":"PRJ","r":"projects","d":"A reusable plan of tasks, activities, milestones and dependencies with due dates relative to the start date, organized by phases or groups","ru":"An existing project can be saved as a template","a":"A project from a template gets dated items from its start date"},{"id":"PRJ-06","n":"Project health","m":"PRJ","r":"projects","d":"A status of on track, at risk, off track or on hold, set manually or suggested by an AI summary of the project's emails, notes, tasks and activities with recommendations","ru":"The AI summary must be enabled per account and can be regenerated","a":"The status shows on the board and in reports"},{"id":"PRJ-07","n":"Collaboration and sharing","m":"PRJ","r":"projects","d":"Notes, files, @mentions and emails on a project, and a one-click AI-written status report as a PDF for clients","ru":"The PDF contains only what the sender chooses to include","a":"A mention on a project notifies the user"},{"id":"PRJ-08","n":"Bulk work and import","m":"PRJ","r":"projects","d":"Paste a list to add many tasks; bulk edit items; import and export project data, including from other project tools","ru":"A date in a pasted line becomes the due date","a":"Pasted lines become tasks in the chosen phase"},{"id":"PRJ-09","n":"Automation and reports","m":"PRJ","r":"projects","d":"Projects and their tasks are triggers and actions in workflows, and Insights has project performance and duration reports","ru":"Uses AUT and INS","a":"A workflow can create a project when a deal is won"},{"id":"LGN-01","n":"Chatbot","m":"LGN","r":"marketing","d":"A scripted website bot built as playbooks in three steps: theme, profile (name, picture, language) and template. Templates: get more leads, book meetings, qualify and route, chat live. Questions can differ per page. Answers create a lead or deal, assign an owner and can book a meeting","ru":"Qualified leads are highlighted at the top of the owner's leads inbox. Per-step drop-off statistics show where visitors leave","a":"A completed conversation creates a lead with the answers stored"},{"id":"LGN-02","n":"Live chat","m":"LGN","r":"marketing","d":"A rep takes over a chat in real time from the web or mobile app","ru":"Chats wait in an unassigned queue for a set time, then fall back to the bot. An online message shows when a rep is available","a":"A claimed chat is locked to one rep and saved on the lead"},{"id":"LGN-03","n":"Web forms","m":"LGN","r":"marketing","d":"A form builder with input and message blocks and templates for contact, registration, gated download, file upload and blank. An introduction block is mandatory. Fields include name, phone, email, marketing status and custom fields, each optionally required. Forms are embedded, linked or shared to social channels, and each has an ID and an active or inactive status","ru":"Submissions become leads or deals, and the owner is notified by email. The current owner is kept on resubmission. Forms capture UTM parameters, cookie values, referral URL and landing page and accept page variables in hidden fields. The form language is fixed at creation. The admin's contact form already creates a ticket and a consented prospect, and forms reuse that path. Tracking fields are on by default and can be switched off (CUS-07)","a":"A submission creates a lead with source and tracking data; views, interactions, submissions and conversion are counted"},{"id":"LGN-04","n":"Prospect search","m":"LGN","r":"marketing","d":"Search of an external business database by person filters (job title, department, location, name) and organization filters (size, industry, type, revenue, location, name, domain, keyword). Saved filters. Credits reveal contact details and add the prospect to the leads inbox","ru":"The database is licensed from a provider, not built. The search itself is built in full. Revealed contacts follow the contact-rule setting, off by default","a":"Revealing a prospect uses one credit and creates a lead"},{"id":"LGN-05","n":"Embedding and consent","m":"LGN","r":"marketing","d":"One script loads chatbot, live chat and tracking on a site. Forms and widgets can carry consent wording and a cookie notice","ru":"Consent-gated loading of widgets is a setting, off by default (CUS-07). One rule is fixed by the admin specification: the tracker and widgets are never loaded in the survey flow","a":"With the consent setting on and consent declined, no tracking cookie is set. No widget ever appears on a survey page"},{"id":"WEB-01","n":"Tracker","m":"WEB","r":"marketing","d":"A script on one or more websites records visits and pages","ru":"Sites are told apart by hostname. The tracker is never loaded in the survey flow, a fixed rule of the admin specification","a":"Visits from each site appear under that site"},{"id":"WEB-02","n":"Organization identification","m":"WEB","r":"marketing","d":"Visits are matched to companies. Internet providers, crawlers and irrelevant traffic are filtered out","ru":"A company counts once per month for billing however often it visits. Data refreshes hourly","a":"A known company IP produces a named visitor"},{"id":"WEB-03","n":"Visitor inbox and ranking","m":"WEB","r":"marketing","d":"A list of visiting companies with location, industry, last visit, source, pages viewed and a ranking by activity","ru":"Filters for period, country, campaign, page and whether the company is already in the CRM","a":"Sorting by quality puts the most active companies first"},{"id":"WEB-04","n":"Convert and reveal","m":"WEB","r":"marketing","d":"A visitor becomes a lead, deal or organization. Prospect search finds people at that company","ru":"Revealing people uses prospect credits (LGN-04)","a":"The created record links to the visit history"},{"id":"DOC-01","n":"Templates and merge fields","m":"DOC","r":"documents","d":"Document, spreadsheet and presentation templates with placeholders for deal, person, organization, product and project fields. Templates are named, categorized and shared company-wide, and can be imported from the connected drive","ru":"Address fields can be split into parts. A missing value is flagged before sending","a":"A document generated from a template contains the deal's data"},{"id":"DOC-02","n":"Product tables","m":"DOC","r":"documents","d":"A table in a template fills with the deal's products, prices, discounts, tax and totals","ru":"Columns are configurable. Not available in spreadsheet templates in the source","a":"Table totals equal the deal value"},{"id":"DOC-03","n":"Cloud storage","m":"DOC","r":"documents","d":"Documents are created and stored in the user's Google Drive, OneDrive or SharePoint, in a personal or shared location","ru":"A default shared location can be set per company. Generated PDFs are always stored in the platform","a":"A new document appears in the connected drive"},{"id":"DOC-04","n":"Trackable links","m":"DOC","r":"documents","d":"A document or uploaded PDF is shared through a link that records each open and notifies the owner","ru":"Links can be disabled","a":"An open is logged with time on the deal"},{"id":"DOC-05","n":"E-signatures","m":"DOC","r":"documents","d":"Signature requests to up to 10 signers with a one-time email code, a custom message, an invite language and signer fields placed by drag and drop","ru":"A signed document is sealed with an audit trail. The legal weight of the signature level must be confirmed for your contracts","a":"A completed request stores the signed PDF and audit trail on the deal"},{"id":"DOC-06","n":"Branding and external signing","m":"DOC","r":"documents","d":"Platform branding can be removed from documents. An external e-signature service can be used instead of the built-in one","ru":"Through an adapter","a":"A document sent through the external service shows its status on the deal"},{"id":"SEC-01","n":"Security dashboard","m":"SEC","r":"security","d":"Right now: users logged in and their locations. Last 7 days: new devices, new locations, security events, forced logouts. An assessment lists high- and low-risk issues with fixes","ru":"Admin only. Each figure opens its list","a":"The figures match the login log"},{"id":"SEC-02","n":"Security alerts","m":"SEC","r":"security","d":"Email alerts when a user logs in from a new device or location, a user is invited, a user has more than 3 failed logins in a row, a password reset is requested, or unusually large exports or deletions happen","ru":"Sent at once or as a digest at a set time","a":"Each trigger produces one alert to admins"},{"id":"SEC-03","n":"Security rules","m":"SEC","r":"security","d":"Company-wide password strength, expiry and reuse rules and access restrictions by IP address and by time","ru":"A preview shows who is affected before enforcing","a":"A login from a blocked IP is refused"},{"id":"SEC-04","n":"Device and login history","m":"SEC","r":"security","d":"Per user: devices, locations, IP addresses, login time and method, session end, for the last 60 days, with remote log-out","ru":"This is a login log. Record changes are audited separately in each record's changelog","a":"Logging out a device ends its session at once"},{"id":"SEC-05","n":"Single sign-on","m":"SEC","r":"security","d":"SAML sign-on with identity providers such as Entra ID and Okta, and sign-in with Google","ru":"A fallback login for admins stays available","a":"A user provisioned at the identity provider can log in without a local password"},{"id":"SEC-06","n":"Two-factor authentication","m":"SEC","r":"security","d":"A second factor at login by email code or authenticator app. Admins can enforce it for everyone. Account recovery and a remembered login email are supported","ru":"None stated.","a":"With enforcement on, no user can log in without the second factor"},{"id":"SEC-07","n":"Permission sets","m":"SEC","r":"settings","d":"Named sets of allowed actions, separate for the deals, projects and campaigns apps and for global features. Admin (full), regular (editable) and custom sets","ru":"Actions include create, edit, delete, import, export, bulk edit, change visibility and view reports. The number of custom sets is an entitlement","a":"A user cannot perform an action missing from their set, in the interface or the API"},{"id":"SEC-08","n":"Visibility groups","m":"SEC","r":"settings","d":"Users sit in groups and sub-groups. Each item is visible to its owner only, the owner's group, the owner's group and sub-groups, or everyone. Defaults are set per record type; pipelines can be limited to groups. A setting decides whether hidden activities and notes show as placeholders","ru":"Enforced by row-level security. The number of custom groups is an entitlement","a":"A user outside the group cannot read the row by any route"},{"id":"SEC-09","n":"Users and teams","m":"SEC","r":"settings","d":"Invite, deactivate and replace users and reassign their records. Teams with a manager and members are used by assignment, reports and goals. Access settings can be copied from another user. A user overview page lists followed items and last login. Users edit their own profile and phone number","ru":"Deactivating a user who owns workflows prompts a transfer (AUT-10)","a":"A deactivated user cannot log in and their records keep an owner"},{"id":"SEC-10","n":"Data protection","m":"SEC","r":"security","d":"Encryption in transit and at rest, isolation of CRM data from survey data, EU hosting and backups with stated recovery objectives","ru":"The source states a one-hour recovery point and two-hour recovery time; your targets are an open decision","a":"A restore test meets the agreed objectives"},{"id":"SEC-11","n":"Privacy compliance","m":"SEC","r":"security","d":"Export and erasure of a person's data on request, consent logs, retention rules and a list of sub-processors","ru":"Erasure covers emails, recordings, transcripts and enrichment data","a":"An erasure request removes the person from every module"},{"id":"INT-01","n":"REST API","m":"INT","r":"platform","d":"Versioned endpoints to list, get, create, update, delete and search every entity, including custom fields, with filtering and pagination, a published API reference, client libraries and request collections","ru":"The API definition is generated from the same registry as the interface, so new fields appear automatically","a":"Every interface action on records is possible through the API"},{"id":"INT-02","n":"Authentication","m":"INT","r":"platform","d":"A personal API token per user, sent in a header, with one active token at a time, and OAuth 2.0 with scopes for apps","ru":"Rotating a token invalidates the old one at once","a":"A revoked token or grant is refused"},{"id":"INT-03","n":"Rate limits","m":"INT","r":"platform","d":"A daily token budget per company (base × plan multiplier × seats), a token cost per endpoint type and a burst limit per token in a rolling 2-second window","ru":"Rate limits are off by default (CUS-07). When they are on, calls over budget return HTTP 429. Admins are emailed at 75% and 100%. A usage dashboard shows consumption","a":"A client over the burst limit gets 429 with limit headers"},{"id":"INT-04","n":"Webhooks","m":"INT","r":"platform","d":"Subscriptions by action (create, change, delete) and object. Each event is an HTTP POST with a JSON body holding current and previous state","ru":"Source limits: 40 webhooks per user, 10-second timeout, retries after 3, 30 and 150 seconds, a 30-minute ban after 10 first-attempt failures, deletion after 3 days without success","a":"A failing endpoint is retried on schedule and then banned"},{"id":"INT-05","n":"Google Workspace","m":"INT","r":"platform","d":"Contacts, calendar, tasks, Drive files, Gmail, Meet links and sign-in","ru":"Uses COM-02, ACT-09, CRM-04 and DOC-03","a":"Each connection can be made and revoked by the user"},{"id":"INT-06","n":"Microsoft 365","m":"INT","r":"platform","d":"Outlook and Exchange mail, calendar, contacts, Teams links and notifications, OneDrive and SharePoint","ru":"Same features as INT-05","a":"Same as INT-05"},{"id":"INT-07","n":"Team chat","m":"INT","r":"platform","d":"Deal events posted to Slack or Microsoft Teams channels or direct messages, and search of deals, people and organizations from chat","ru":"Also a workflow action (AUT-07)","a":"A won deal posts to the configured channel"},{"id":"INT-08","n":"Invoicing","m":"INT","r":"platform","d":"An invoice is created in the accounting system from a deal with its person, organization and products, and its status shows on the deal","ru":"Through an adapter; which accounting system to support first is part of open point 2","a":"An invoice created from a deal carries the deal's lines"},{"id":"INT-09","n":"Automation platforms","m":"INT","r":"platform","d":"Connectors for no-code automation platforms, built on the API and webhooks","ru":"None stated.","a":"A new deal can trigger an external automation"},{"id":"INT-10","n":"App extensions","m":"INT","r":"platform","d":"Integrations can show panels inside deal and contact detail views and offer actions that open a link, a dialog or embedded interface","ru":"Panels are sandboxed and get only the data their scopes allow","a":"An installed extension shows its panel on the detail view"},{"id":"INT-11","n":"Integration catalog","m":"INT","r":"platform","d":"A list of available integrations, grouped in collections by sales stage and tagged by function, with what each can access, an install step, settings, per-user management and removal","ru":"Third-party apps built on the app platform (INT-02, INT-10) can be listed beside the first-party connectors","a":"Removing an integration revokes its access"},{"id":"MOB-01","n":"Core app","m":"MOB","r":"mobile","d":"Pipeline, deals, leads, contacts, activities (list and calendar), detail views, filters and search, synced in real time with the web app, in portrait and landscape, with import of phone contacts","ru":"Same permissions as the web app","a":"A change on mobile appears on the web without refresh"},{"id":"MOB-02","n":"Focus view","m":"MOB","r":"mobile","d":"The opening screen: overdue activities and deals, unread email count, nearby count, and activities and expected closes for today and the coming week, plus an agenda widget for the phone's home screen","ru":"None stated.","a":"Counts match the same filters on the web"},{"id":"MOB-03","n":"Nearby","m":"MOB","r":"mobile","d":"A map of deals, organizations and people near the user's location, with filters, including address custom fields, and a hand-off to a navigation app","ru":"Needs location permission","a":"Tapping a pin opens the record"},{"id":"MOB-04","n":"Calls and texts","m":"MOB","r":"mobile","d":"Calls from the app are logged as activities. Incoming callers are matched to contacts. A text opens the phone's messaging app with the number filled","ru":"As in the source, iOS logs only outgoing calls made in the app, while Android logs calls in full","a":"A call from the app creates an activity"},{"id":"MOB-05","n":"Offline mode","m":"MOB","r":"mobile","d":"Deals, notes and activities can be changed offline and sync when the connection returns; a sync can also be forced manually","ru":"Conflicts are resolved by the latest change, with the earlier value kept in the changelog","a":"Offline changes appear after reconnecting"},{"id":"MOB-06","n":"Capture","m":"MOB","r":"mobile","d":"Audio notes with transcription, a scanner that turns handwritten or printed notes into text, photo and file upload, sharing content from other apps into the CRM, and the card scanner (AIA-07)","ru":"None stated.","a":"A scanned note is saved on the chosen record"},{"id":"MOB-07","n":"Push notifications","m":"MOB","r":"mobile","d":"Reminders, assignments, mentions and chat requests","ru":"Configurable per type","a":"A new assignment sends one push"},{"id":"MOB-08","n":"Mobile extras","m":"MOB","r":"mobile","d":"Live chat takeover, project tasks and a statistics dashboard","ru":"Project support may follow the web release, as in the source","a":"A rep can answer a live chat from the phone"},{"id":"ENT-01","n":"Feature gating","m":"ENT","r":"settings","d":"Each feature is switched on per plan and add-on from an entitlement table","ru":"Checked in the interface, the API and the workflow engine","a":"A gated feature is unavailable through every channel"},{"id":"ENT-02","n":"Usage limits","m":"ENT","r":"settings","d":"Metered limits per company or per seat: leads and deals, custom fields, reports, active workflows, branches per workflow, sequences, mailboxes, team inboxes, teams, visibility groups, permission sets, scoring models, enrichment credits, formula fields, API tokens","ru":"The source's values per plan are in the inventory's usage-limits table. Every limit is unlimited until an admin sets a value","a":"A limit is enforced at the moment of creation"},{"id":"ENT-03","n":"Plans, add-ons and top-ups","m":"ENT","r":"settings","d":"Seat-based plans, add-ons priced per company, per seat or by volume, credit top-ups and a free trial","ru":"Uses the existing billing","a":"Buying an add-on enables its features at once"},{"id":"ENT-04","n":"Usage screen and limit handling","m":"ENT","r":"settings","d":"A page showing consumption against every limit. At a limit, new additions are blocked and nothing is deleted; overflow goes to the waitlist or the import skip file","ru":"Warnings before the limit is reached","a":"The usage page matches actual counts"}],"flows":[{"id":"UF-01","n":"Capture and qualify a lead","s":["A lead arrives from a form, chatbot, import, prospect search or manual entry, with its source recorded.","An assignment rule sets the owner; the owner is notified.","The rep opens the lead, reads the enriched company data and any chat or form answers.","The rep emails or calls; the contact is logged on the lead.","If the lead is not relevant, the rep labels and archives it. The flow ends.","If qualified, the rep converts it to a deal and picks pipeline and stage.","Notes, emails, files and activities move to the deal, and the rep is prompted to plan the next activity."],"h":"Actor: sales rep. Uses LEA-01 to LEA-05, AUT-11, PRO-04, CRM-15, ACT-07."},{"id":"UF-02","n":"Work a deal to won or lost","s":["The rep opens the pipeline; cards without a planned activity show a warning and idle deals show as rotting.","The rep opens a deal and reads Focus and History.","The rep completes the due activity and plans the next one when prompted.","The rep drags the deal to the next stage. If a required field is empty, the move is blocked until it is filled.","The rep adds products; the deal value recalculates.","The rep marks the deal won, or marks it lost and gives a reason.","Workflows listening for that change run (for example, creating a project)."],"h":"Actor: sales rep. Uses PIP-01 to PIP-07, CUS-02, CRM-07, ACT-01, ACT-04, ACT-07."},{"id":"UF-03","n":"Daily routine in the feed","s":["The rep opens the feed on the Follow-ups tab and sees replies, opened emails, today's activities and emails waiting to send.","For each card the rep acts from the card or opens the side panel.","The Overlooked deals tab lists deals with no follow-up or overdue activities; the rep schedules a next step for each.","The Opportunities tab lists new deals with no activity; the rep plans a first step.","The rep filters by score to take the best deals first. The counter shows what is done."],"h":"Actor: sales rep. Uses PRO-01, PRO-02, PRO-03, COM-06."},{"id":"UF-04","n":"Email outreach with tracking","s":["From a deal, the rep opens the composer and picks a template or asks the AI writer for a draft.","Merge fields fill; a missing value is flagged.","The rep sends now or schedules.","If sending fails, the outbox shows the reason and the rep retries.","When the contact opens or clicks, the rep is notified.","If the contact replies, the thread links to the deal and the rep can ask for a summary and suggested reply.","If there is no reply after 5 days, a follow-up card appears in the feed."],"h":"Actor: sales rep. Uses COM-02, COM-05, COM-06, COM-08, AIA-03, AIA-04."},{"id":"UF-05","n":"Nurture with a sequence","s":["The user builds a sequence of email and activity steps with delays.","The user enrolls leads or deals one by one or in bulk, or a workflow enrolls them.","Automatic email steps send at the planned time; manual ones wait for the rep to review and send.","Activity steps create activities for the owner.","If the contact replies or the deal changes stage, enrollment ends.","Otherwise the record completes the sequence. A failed step marks the enrollment failed with the reason."],"h":"Actor: sales rep or manager. Uses AUT-12, COM-05, ACT-01."},{"id":"UF-06","n":"Book a meeting","s":["The rep sets availability once and puts a booking link in an email, signature or automated message.","The contact opens the booking page, sees free slots in their own time zone and picks one.","Both receive a confirmation; an activity with a video link is created on the deal.","The slot disappears for other invitees and the event syncs to the rep's calendar.","If the contact reschedules or cancels, the activity and calendar event are updated."],"h":"Actors: sales rep and contact. Uses COM-10, COM-11, ACT-08, ACT-09."},{"id":"UF-07","n":"Run a meeting with meeting intelligence","s":["Before the meeting the rep reads the brief.","Attendees are notified of recording. The bot joins the call, or the rep records with the desktop app.","If an attendee objects, the rep removes the bot or stops recording.","After the call the recap and transcript are saved on the deal and a chat message announces it.","The rep reviews the suggested CRM updates and approves the ones that are right.","The rep sends a follow-up drafted from the recap and plans the next activity."],"h":"Actor: sales rep. Uses MTG-01 to MTG-08, AIA-03."},{"id":"UF-08","n":"Quote to signature","s":["From the deal's Documents tab the rep picks a template.","The document is generated with deal data and a product table and opens for editing.","The rep shares it by trackable link or requests signatures, adding signers and a message.","The customer opens the document; the rep is notified.","Each signer enters the emailed code and signs.","The signed PDF and audit trail are stored on the deal, and a workflow can move the deal to won.","If nobody opens or signs, the rep sees the status and follows up."],"h":"Actors: sales rep and customer. Uses DOC-01 to DOC-06, CRM-07, AUT-01."},{"id":"UF-09","n":"Set up the sales process","s":["The admin creates pipelines and stages with probabilities and rotting thresholds.","The admin adds custom fields, groups them and marks important and required ones.","The admin sets activity types, currencies and which modules are on.","The admin invites users, places them in teams and visibility groups and assigns permission sets.","The admin tests with a sample deal. In a sandbox, nothing reaches the live company."],"h":"Actor: admin. Uses PIP-02, PIP-14, CUS-01 to CUS-08, ACT-02, SEC-07 to SEC-09."},{"id":"UF-10","n":"Import and clean data","s":["The admin uploads a spreadsheet and confirms or corrects the suggested column mapping.","The system previews duplicates; the admin chooses merge or create.","The import runs. Rows that fail validation or exceed capacity go to the skip file.","The admin downloads the skip file, fixes it and imports again.","The admin reviews suggested duplicates and merges them.","If the import was wrong, the admin reverts it from the import history."],"h":"Actor: admin. Uses CRM-09, AIA-05, CRM-11, CRM-12, ENT-04."},{"id":"UF-11","n":"Build a workflow","s":["The user starts from a template or a blank canvas.","The user picks an event or date trigger and adds conditions.","The user adds actions, delays, wait-for steps and branches.","The user saves a draft, then activates it for themselves, selected users or a team.","Matching events start runs. The history shows each run.","If a step fails, the owner is alerted and opens the failing step from the overview.","If a limit has been set and is reached, activation is refused with the reason."],"h":"Actor: admin or permitted user. Uses AUT-01 to AUT-10."},{"id":"UF-12","n":"Set up automatic assignment","s":["The admin creates a rule for lead added, deal added or deal updated.","The admin sets conditions and the assignee: user, team, organization owner or person owner.","The admin orders the rules by priority and activates them.","New records are assigned by the first matching rule; with no match the creator stays owner.","The admin checks the assignment history to see which rule fired."],"h":"Actor: admin. Uses AUT-11, SEC-09."},{"id":"UF-13","n":"Reports, dashboards and goals","s":["The manager creates a report by choosing a type or typing a request for the AI generator.","The manager sets measure, dimensions, filters and chart type.","The manager adds reports to a dashboard, arranges them and shares the dashboard with the team or by public link.","The manager creates goals for users or teams and tracks progress.","The manager exports a chart or the underlying rows when needed."],"h":"Actor: manager. Uses INS-01 to INS-10."},{"id":"UF-14","n":"Scoring and enrichment","s":["The admin creates a scoring model for a pipeline and adds criteria to the three groups.","The preview shows how sample deals score; the admin activates the model.","Scores appear on deals and in the feed filter.","A rep enriches an organization or selects up to 100 records for bulk enrichment.","If a credit allowance is set and credits are short, the request is refused and the admin can buy a top-up.","Enriched fields update scores that depend on them."],"h":"Actor: admin and sales rep. Uses PRO-03 to PRO-06."},{"id":"UF-15","n":"Security administration","s":["The admin opens the security dashboard and works through the assessment.","The admin configures single sign-on and enforces two-factor authentication.","The admin sets password, IP and time rules, previews who is affected and enforces them.","The admin chooses alerts and how they are delivered.","On an alert the admin checks the login history and logs the device out.","On a privacy request the admin exports or erases the person's data."],"h":"Actor: admin. Uses SEC-01 to SEC-06, SEC-10, SEC-11."},{"id":"UF-16","n":"Connect systems","s":["The user connects Google or Microsoft for mail, calendar, contacts and files.","A developer creates an API token or registers an OAuth app and reads the API reference.","The developer subscribes webhooks to events.","If an endpoint keeps failing, the webhook is banned and later removed; the developer sees this in the webhook list.","The admin finds integrations in the catalog by search or recommendation, installs them and reviews their access.","The admin switches the AI connector on or off for the company."],"h":"Actor: admin or developer. Uses INT-01 to INT-11, MCP-01 to MCP-03, AIA-06."},{"id":"UF-17","n":"Send an email campaign","s":["The marketer authenticates the sender domain; sending stays blocked until it passes.","The marketer builds the email from a template in the editor and previews desktop and mobile.","The marketer picks the audience with a filter; only subscribed addresses are counted.","The marketer sends now or schedules.","Bounces, unsubscribes and spam reports update each address's status.","The marketer reads the campaign report and compares it with earlier campaigns."],"h":"Actor: marketer. Uses CMP-01 to CMP-09."},{"id":"UF-18","n":"Website visitor to lead","s":["A visitor opens a page and the widget loads; if consent-gated loading is switched on, it loads according to consent.","The chatbot asks its questions for that page.","If the visitor qualifies, the bot offers a meeting slot or a live chat.","If a rep is online and claims the chat within the waiting time, the rep takes over; otherwise the bot continues and collects contact details.","A lead is created with the answers, source and tracking data and assigned by rule.","Alternatively the visitor submits a web form, which creates the lead the same way."],"h":"Actors: visitor and sales rep. Uses LGN-01 to LGN-05, LEA-01, AUT-11, COM-10."},{"id":"UF-19","n":"Identify web visitors","s":["The admin installs the tracker on the website.","Visiting companies appear in the visitor inbox, ranked by activity.","The rep filters by country, campaign or page and opens a company's visit history.","If the company is already in the CRM, the rep sees the existing record.","Otherwise the rep converts it to a lead or organization and uses prospect search to find contacts."],"h":"Actor: sales rep. Uses WEB-01 to WEB-04, LGN-04."},{"id":"UF-20","n":"Hand over a won deal to delivery","s":["A deal is marked won; a workflow or the rep creates a project from it, optionally from a template.","The project brief is drafted from the deal and reviewed.","The project manager adjusts tasks, owners, dates and dependencies on the timeline.","The team works the tasks; the board shows phase and health.","If the project slips, the manager sets the health status or requests an AI summary with recommendations.","The manager shares a status report with the client and closes the project when done."],"h":"Actors: sales rep and project manager. Uses PRJ-01 to PRJ-09, AUT-07."},{"id":"UF-21","n":"Field visit on mobile","s":["The rep opens the app on the focus view and sees the day.","The rep checks Nearby for contacts around the next meeting and navigates there.","Without a connection the rep still opens the deal and adds notes.","After the meeting the rep records an audio note, scans a business card and plans the next activity.","Changes sync when the connection returns."],"h":"Actor: sales rep. Uses MOB-01 to MOB-08, AIA-07."},{"id":"UF-22","n":"Work through an external AI assistant","s":["The user adds the connector in their AI assistant and logs in.","The user asks the assistant to find, create or update records in plain language.","The assistant calls tools; each call runs with the user's permissions and counts against API limits.","If the admin has switched the connector off, the connection is refused.","Changes made through the assistant appear in the changelog with the connector as source."],"h":"Actor: any user. Uses MCP-01 to MCP-03, INT-03."},{"id":"UF-23","n":"Manage contacts and organizations","s":["The user opens an organization and sees its contacts, deals, tickets, activities and files.","The user adds a contact. Source and basis are optional by default and required only if the contact-rule setting is on.","The user adds a note, mentions a colleague and attaches a file.","The user links a parent organization and applies labels.","The contacts timeline shows who has had no contact in the chosen period; the map shows contacts near a place.","With contact sync connected, changes flow to and from the user's address book.","The user exports a filtered list; the export is logged."],"h":"Actor: sales rep or admin. Uses CRM-01 to CRM-06, CRM-10, CRM-13, CRM-14."},{"id":"UF-24","n":"Review and maintain the pipeline","s":["The user searches for a record or applies a saved filter.","In the list view the user picks columns, sorts and edits cells inline.","The user selects several deals and bulk edits an owner or label, or adds an activity to all of them.","The user adds participants to a deal and follows a colleague's deal.","In the calendar the user reschedules activities and sets priorities.","The user archives dead deals, shows closed deals to review them, duplicates a deal and restores one deleted by mistake.","If a bulk delete is requested, a preview is shown. A second admin must approve it only if that setting is on."],"h":"Actor: sales rep or manager. Uses PIP-08 to PIP-13, PIP-15, PIP-17, ACT-03, ACT-05, ACT-06."},{"id":"UF-25","n":"Calls, messages and shared inboxes","s":["The rep clicks a phone number; the call runs through the telephony provider and is logged with outcome and duration.","A message from a contact arrives in the messaging inbox and notifies the owner.","The rep answers an email in a shared inbox; colleagues see the reply on the thread.","The rep picks the sending mailbox, labels the thread and archives it.","The rep sends one email to a selected list. By default every recipient gets the email. If the consent setting is on, recipients without a consent basis or on the suppression list are left out and reported.","Working in the mail client, the rep adds a deal from the side panel. Without mail sync, the rep copies in the BCC address instead."],"h":"Actor: sales rep. Uses COM-01, COM-03, COM-04, COM-07, COM-09, COM-12, COM-13, COM-14, LEA-06."},{"id":"UF-26","n":"Recurring revenue and forecast","s":["The rep adds a recurring product or an installment plan to a deal.","The deal shows MRR, ARR, ACV and TCV.","The manager opens the forecast view and drags a deal to a later month.","The forecast reports show expected revenue by month from deals and from recurring products.","For existing Orgpuls customers the recurring figures come from billing, not from deals."],"h":"Actors: sales rep and manager. Uses CRM-08, PIP-11, INS-06."},{"id":"UF-27","n":"Work with the AI assistant","s":["The user asks the assistant about deals or contacts; the answer cites the records used.","A question about survey answers is refused, because that data is outside the assistant's reach.","The user opens the notifications panel and sees deals flagged as stalled, each with a suggested next step.","The user accepts a suggestion; the action runs and is logged.","For an email from an unknown sender the assistant proposes a contact, and the user accepts it to create the record."],"h":"Actor: any staff user. Uses AIA-01, AIA-02, PRO-07."},{"id":"UF-28","n":"Plans and limits","s":["The admin opens the usage page and sees consumption against each limit.","At a limit a manual creation is refused, and automated lead and deal creation goes to the waitlist.","The admin upgrades the plan or buys a top-up; the feature or allowance is available at once.","The admin adds the waitlisted deals back."],"h":"Actor: admin. Uses ENT-01 to ENT-03, PIP-16. By default nothing is limited; this flow applies once an admin sets plans or limits."},{"id":"UF-29","n":"Set rules and limits","s":["The admin opens Settings and sees every rule with its current value; by default all are unrestricted.","The admin switches on a rule, for example the contact rule or consent checks on sales email, and picks warn or block where offered.","The admin sets a limit or a plan gate if one is wanted.","The change applies at once and is logged with who and when.","A user who then hits a rule sees which setting stopped the action.","Switching the rule off restores full function."],"h":"Actor: admin. Uses CUS-07, ENT-01, ENT-02."},{"id":"SF-01","n":"Permission and visibility check","s":["The request is authenticated and tied to a staff user, a role and a product.","The user's permission sets decide whether the action is allowed at all.","Row-level security decides which rows match: owner, the owner's group, the group and its sub-groups, or everyone.","Field rules remove hidden fields and reject writes to read-only ones.","Where entitlements are in use, the check confirms the feature is switched on.","A refusal returns a clear error and is logged. A read of customer-scoped data writes an audit row; a typed reason is asked for only if that setting is on. Survey response tables are unreachable from every CRM function."],"h":"Runs on every read and write. Serves SEC-07, SEC-08, CUS-03, ENT-01."},{"id":"SF-02","n":"Record change and event publication","s":["The change, its changelog entry and an event are written in one transaction.","A dispatcher reads new events and delivers them to subscribers: workflows, assignment, scoring, feed, report rollups, webhooks, notifications.","Each subscriber processes an event once, identified by its ID.","A subscriber that fails retries without blocking the others."],"h":"Triggered by any create, update or delete. Serves PIP-04, AUT, INT-04, INS-10."},{"id":"SF-03","n":"Email sync","s":["The user authorizes the mailbox; tokens are stored encrypted.","History is loaded back to the chosen start date.","New mail arrives by provider notification or polling and is stored.","Senders and recipients are matched to people; the thread links to their open deal or lead, or waits for manual linking.","Outgoing mail is sent through the provider with tracking added, then stored.","Opens and clicks come back as events and notify the sender.","If a token expires or a send fails, the user is asked to reconnect or sees the failure reason in the outbox."],"h":"Triggered by a mailbox connection and by new mail. Serves COM-01 to COM-09."},{"id":"SF-04","n":"Workflow execution","s":["The engine finds active workflows whose trigger matches.","Conditions are evaluated; a failed condition ends silently.","A run is created and steps execute in order with the owner's permissions.","A delay schedules the next step; a wait-for step listens for its condition and stops the run after 7 days.","A branch picks one path.","Each step's result is written to the run history.","A failed action marks the run failed and alerts the owner. Run counters stop loops when the rolling limit is passed."],"h":"Triggered by an event or a date. Serves AUT-01 to AUT-10."},{"id":"SF-05","n":"Sequence scheduler","s":["On enrollment the first step's time is computed, skipping weekends if set.","If the consent setting is on, consent basis and the suppression list are checked first. Then an automatic email is sent, a manual email is queued in the feed, or an activity is created.","The next step is scheduled.","A reply or a stage change ends the enrollment.","After the last step the enrollment is completed; a failed send marks it failed."],"h":"Triggered by enrollment. Serves AUT-12."},{"id":"SF-06","n":"Assignment engine","s":["Active rules for that event are loaded in priority order.","The first rule whose conditions match is chosen.","The assignee is resolved: a user, the next member of a team in rotation, the organization's owner or the person's owner.","The owner is set, the evaluation is logged and the new owner is notified.","With no match the record keeps its owner."],"h":"Triggered when a lead is added or a deal is added or updated. Serves AUT-11."},{"id":"SF-07","n":"Notifications and reminders","s":["The source emits a notification request.","The service applies the user's channel preferences.","It delivers in the app, by email or by push.","Duplicates within a short window are merged."],"h":"Triggered by due activities, mentions, assignments, email events and AI cards. Serves ACT-04, CRM-06, MOB-07."},{"id":"SF-08","n":"Calendar sync","s":["The user connects a calendar and picks the direction and activity types.","Activity changes are pushed to the calendar.","Calendar changes arrive by notification and update activities.","Private events are stored as busy time without details.","Conflicting edits resolve to the latest change."],"h":"Triggered by changes on either side. Serves ACT-08, ACT-09, COM-10."},{"id":"SF-09","n":"Import pipeline","s":["The file is parsed and a column mapping is suggested.","The user confirms the mapping and the duplicate rule.","Rows are validated; capacity is checked.","Valid rows are written in batches, tagged with the import ID.","Rejected rows go to a skip file with reasons.","The import history records counts; a revert deletes or restores by import ID."],"h":"Triggered by an upload. Serves CRM-09, AIA-05, ENT-04."},{"id":"SF-10","n":"Duplicate detection and merge","s":["New people and organizations are compared with existing ones by the configured matching rules.","Matches are listed as suggestions.","On merge, the user picks surviving values.","Linked deals, activities, emails and files move to the survivor and the other record is soft-deleted."],"h":"Triggered by record creation and on demand. Serves CRM-11."},{"id":"SF-11","n":"Enrichment","s":["Where a credit allowance is set, the balance is checked and a short balance refuses the request.","The provider adapter is called with name, domain or profile.","Returned values are mapped to fields.","Only empty fields are written, with source and date.","Credits are deducted and scoring is re-run for affected deals.","A provider error leaves the record unchanged and uses no credit."],"h":"Triggered by a user request, single or bulk. Serves PRO-04 to PRO-07."},{"id":"SF-12","n":"Scoring","s":["The active model for the deal's pipeline is loaded.","Each criterion is evaluated and its group's points are added.","The total is normalized to 0–100.","The score and the matched criteria are stored and a score-changed event is published."],"h":"Triggered by a deal change or a model change. Serves PRO-03."},{"id":"SF-13","n":"Feed generation","s":["Events such as a reply, an open, a click or a new deal create cards for the deal's owner.","Scheduled checks create cards for no reply after 5 days, no follow-up and overdue activities.","A card is resolved when its condition no longer holds or the user acts.","The daily counter is updated."],"h":"Triggered by events and scheduled checks. Serves PRO-01, PRO-02."},{"id":"SF-14","n":"Report query","s":["The report definition is turned into a query.","The query runs under the viewer's visibility, on live tables or rollups.","Results are cached per definition and data scope.","Related events invalidate the cache.","A public link runs with the owner's scope and nothing else."],"h":"Triggered when a report or dashboard opens. Serves INS-01 to INS-10."},{"id":"SF-15","n":"Delete, restore and erasure","s":["A delete marks the row and records who, when and from where.","The item is listed for restore for 30 days.","A restore brings back the row and its links.","After 30 days a job removes it permanently.","An erasure request removes a person from every module at once and is logged."],"h":"Triggered by a delete, a restore or a privacy request. Serves CRM-12, SEC-11."},{"id":"SF-16","n":"Entitlements and metering","s":["If a limit is set, the counter for the item is compared with it; by default there is none.","Under the limit the creation proceeds and the counter rises.","At the limit a manual creation is refused with the reason.","An automated creation of a lead or deal goes to the waitlist instead.","The usage page reads the same counters."],"h":"Triggered by any creation of a limited item. Serves ENT-01 to ENT-04, PIP-16."},{"id":"SF-17","n":"Lead capture from forms and chat","s":["The widget loads. If consent-gated loading is switched on, it loads only what consent allows. It never loads in the survey flow.","The submission is validated and checked for spam.","A contact and organization are found or created; source and any consent given are recorded. The admin's contact-form path, which also opens a ticket, is reused.","A lead or deal is created with answers, source and tracking data.","Assignment runs, the owner is notified and workflows fire.","A resubmission updates the existing record and keeps its owner."],"h":"Triggered by a form submission or a finished chat. Serves LGN-01 to LGN-05, LEA-04."},{"id":"SF-18","n":"Web visitor identification","s":["The tracker sends page, referrer and network address.","The address is matched to a company through the data source.","Internet providers, crawlers and unmatched traffic are dropped.","The company's visit is stored and its monthly unique count and ranking are updated.","The visitor inbox refreshes hourly."],"h":"Triggered by a page view on a tracked site. Serves WEB-01 to WEB-04."},{"id":"SF-19","n":"Campaign send","s":["The audience filter is resolved and reduced to subscribed addresses.","Each email is rendered with the recipient's data.","Messages go to the sending provider on the marketing stream.","Provider events return: delivered, bounced, opened, clicked, unsubscribed, complaint.","Events update the campaign figures and each address's status.","An unauthenticated domain or a suspended account blocks the send before step 3."],"h":"Triggered at the scheduled time. Serves CMP-03 to CMP-08."},{"id":"SF-20","n":"Document and signature","s":["The template's placeholders are filled from the deal and the file is saved to the connected drive.","A share link is created; each open is logged and notified.","A signature request emails each signer a link and a one-time code.","Each signature is recorded with time and address.","When all have signed, the PDF is sealed with its audit trail and stored on the deal.","An event is published so workflows can react."],"h":"Triggered from a deal. Serves DOC-01 to DOC-06."},{"id":"SF-21","n":"Meeting intelligence pipeline","s":["Upcoming meetings are read from the calendar and linked to deals.","A brief is generated from the deal's history and stored before the meeting.","The bot joins or the desktop app captures audio.","Audio is transcribed with speakers and timestamps.","The AI gateway produces the recap and the proposed field changes.","The recap is saved as a note and announced.","Only approved changes are written. A failed transcription leaves the recording available for retry."],"h":"Triggered by a calendar event or a manual recording. Serves MTG-01 to MTG-08."},{"id":"SF-22","n":"API request and rate limiting","s":["The token or OAuth grant is verified.","If rate limits are switched on, the burst limiter checks the rolling 2-second window for that token.","With rate limits on, the endpoint's token cost is deducted from the daily budget.","The permission check of SF-01 runs.","The handler responds with limit headers.","Over either limit the response is HTTP 429. Admins are emailed at 75% and 100% of the daily budget."],"h":"Triggered by every API and connector call. Serves INT-01 to INT-03, MCP-01."},{"id":"SF-23","n":"Webhook delivery","s":["Subscriptions matching the action and object are found.","The payload is posted with a 10-second timeout.","On failure it is retried after 3, 30 and 150 seconds.","Ten first-attempt failures ban the webhook for 30 minutes.","Three days without a success delete it and notify its owner."],"h":"Triggered by an event with subscribers. Serves INT-04, AUT-07."},{"id":"SF-24","n":"AI gateway call","s":["The feature sends a request with the user and the records in scope.","Context is retrieved under the user's permissions, and never from survey response tables.","The prompt is assembled and sent to the model provider under a no-training agreement.","The output is validated against the expected structure.","The call is logged with feature, user and cost.","An invalid output is retried once, then returned as an error."],"h":"Triggered by any AI feature. Serves AIA-01 to AIA-05, MTG, PRJ-06, INS-09."},{"id":"SF-25","n":"Search","s":["Each write updates a search index with the record's name, emails, phones and text fields.","A query is matched against the index.","Results are filtered by the user's role and visibility.","Results are ranked and grouped by record type.","Survey data is never indexed."],"h":"Triggered by a query. Serves PIP-12."},{"id":"SF-26","n":"Scheduled checks","s":["A scheduler starts each check at its interval.","The rotting check flags deals idle past their stage threshold and notifies owners.","The date-trigger check starts workflows whose date condition is met.","The goal check recomputes progress.","The feed check creates no-reply and no-follow-up cards.","Each check records its run; a failed run raises an alert."],"h":"Triggered on a schedule. Serves PIP-05, AUT-03, INS-05, PRO-01."},{"id":"SF-27","n":"Sign-in and security events","s":["The user signs in with a password or single sign-on.","The second factor is checked; it is mandatory in the admin.","Security rules are applied: IP allowlist, time window, password age.","The login is written to the login log with device and location.","A new device or location, or repeated failures, sends an alert.","The security dashboard reads the same log."],"h":"Triggered by a login. Serves SEC-01 to SEC-06."},{"id":"SF-28","n":"Calls and messages","s":["A click-to-call request goes to the telephony adapter.","The provider reports the result, and an activity is written with outcome, duration and recording link.","An incoming number is matched to a contact.","An incoming message is stored on its thread, linked to the contact's open deal and notified to the owner.","An unmatched number or sender is listed for manual linking."],"h":"Triggered by a call or an incoming message. Serves COM-12, COM-13, MOB-04."},{"id":"SF-29","n":"Contact sync","s":["The user connects an address book and chooses what syncs.","Records are matched by email address.","A change on one side updates the other.","A new external contact is imported. If the contact-rule setting is on, it must pass that rule first."],"h":"Triggered by a change on either side. Serves CRM-04."},{"id":"SF-30","n":"Live chat routing","s":["The chat enters the unassigned queue and online reps are notified.","The first rep to claim it gets the conversation, which is then locked to that rep.","If nobody claims it within the waiting time, the bot continues.","Messages are delivered in real time in both directions.","The transcript is saved on the lead."],"h":"Triggered when a visitor asks for a person. Serves LGN-02."},{"id":"SF-31","n":"Mobile offline sync","s":["Offline changes are queued on the device with their time.","On reconnecting they are sent in order.","Each is applied if the record has not changed since; otherwise the latest change wins and the earlier value stays in the changelog.","The device then pulls changes made elsewhere."],"h":"Triggered when a device reconnects. Serves MOB-05."},{"id":"SF-32","n":"Derived values","s":["A product line change recalculates the deal value.","A schedule change recalculates MRR, ARR, ACV and TCV.","A change to a formula input recalculates the formula field.","Reports convert amounts with the stored exchange rate.","A stage change closes the time in the previous stage and opens the next."],"h":"Triggered by a change to an input. Serves CRM-07, CRM-08, CUS-04, CUS-06, PIP-15."},{"id":"SF-33","n":"Files","s":["The file is uploaded to storage under the record's access rules.","A file row links it to the record and its history.","A download is allowed only if the user may see the record.","Deleting the record soft-deletes its files with it."],"h":"Triggered by an upload. Serves CRM-05, DOC-03, MOB-06."},{"id":"SF-34","n":"Rule settings","s":["The feature asks the settings registry for the rules that apply to it.","With default settings no rule applies and the action proceeds.","If a rule is on, it is evaluated and returns allow, warn or block.","A block names the setting that caused it.","Every change to a setting is logged.","The anonymity firewall is not in the registry and cannot be switched off."],"h":"Triggered whenever a feature with an optional rule runs. Serves CUS-07, ENT-01, ENT-02."},{"id":"SF-35","n":"Deal lifecycle","s":["A deal is created in a pipeline and stage with its owner; field quality rules are checked.","A stage move, or a date change in the forecast view, is saved optimistically, written to the stage history and published as an event.","Deleting a stage moves its deals to the chosen target stage.","Closing as won or lost stores the status and the lost reason.","Archiving removes the deal from active views; unarchiving returns it.","A duplicate copies fields and products; a restore returns a deleted deal to its former stage."],"h":"Triggered when a deal is created, moved, closed, archived, duplicated or restored. Serves PIP-01, PIP-02, PIP-03, PIP-06, PIP-07, PIP-11, PIP-13, PIP-14, PIP-17."},{"id":"SF-36","n":"Activity lifecycle","s":["An activity is created with its type, owner, time and linked record; a bulk request creates one per selected record.","Custom activity types and fields come from the registry.","A reschedule in the calendar updates the activity and any synced event.","Completing it stamps time and user and publishes an event.","If the deal then has no open activity, the next-step prompt is shown and the card gets the warning icon."],"h":"Triggered when an activity is created, changed or completed. Serves ACT-01, ACT-02, ACT-03, ACT-05, ACT-06, ACT-07."},{"id":"SF-37","n":"Records, links and list operations","s":["A person or organization is created or updated on the admin's contact and organization records, with its source stored.","Labels, related organizations, participants and followers are stored as links; a follower is notified of changes.","A new address is geocoded once for the map.","The timeline is built from the record's activities and messages.","A bulk edit writes one changelog entry per record; a bulk delete shows a preview first.","An export writes the visible rows and columns to a file and is logged."],"h":"Triggered by changes to people, organizations and their links, and by list actions. Serves CRM-01, CRM-02, CRM-03, CRM-10, CRM-13, CRM-14, CRM-15, PIP-08, PIP-09, PIP-10."},{"id":"SF-38","n":"Field and configuration registry","s":["A field, quality rule or translation is saved as a versioned row.","Forms, filters, reports, import and the API read the registry, so the change appears without a deploy.","Quality rules are evaluated on save and on stage moves.","Interface text is served from the translation catalog in the user's language.","The demo tenant has its own configuration and sample data, kept apart from live data."],"h":"Triggered when an admin changes configuration, and read by every screen. Serves CUS-01, CUS-02, CUS-05, CUS-08."},{"id":"SF-39","n":"Campaign authoring and insights","s":["The builder saves the design as rows and blocks; the footer is added automatically.","A design is saved to or loaded from the template store.","A test send and the desktop and mobile previews render the same output as the final send.","Provider events are rolled up per campaign.","Insights reads the rollups for performance, conversion and comparison reports."],"h":"Triggered when a marketer builds a campaign or opens its reports. Serves CMP-01, CMP-02, CMP-09."},{"id":"SF-40","n":"Video links and mail client add-ons","s":["Scheduling a meeting asks the connected video provider for a link and stores it on the activity and the invite.","If the provider fails, the activity is saved without a link and the user is told.","The mail client add-on signs in as the user and calls the same API as the web app.","Records created in the add-on carry the add-on as their source."],"h":"Triggered when a meeting is scheduled or an add-on calls the API. Serves COM-11, COM-14."},{"id":"SF-41","n":"Connectors, app platform and AI connector tools","s":["The user or admin installs a connector from the catalog and grants its scopes through OAuth.","The connector's status and error rate are reported to the admin's integrations status.","Deal events are posted to team chat; an invoice request goes to the accounting adapter and its status comes back.","Extension panels load in a sandbox with only the data their scopes allow.","AI connector tools are generated from the API definitions; the company switch blocks all of them at once.","Removing a connector revokes its grants."],"h":"Triggered when a connector or app is installed, used or removed. Serves INT-05 to INT-11, AIA-06, MCP-02, MCP-03."},{"id":"SF-42","n":"Project lifecycle","s":["A project is created from a won deal or from scratch, optionally from a template whose dates are set from the start date.","Tasks, subtasks, milestones and activities are added one by one, pasted in bulk or imported.","A dependency is saved unless it would form a cycle.","Dragging a phase on the timeline shifts its items and keeps their spacing.","A phase change publishes an event for workflows and reports.","Notes, files, mentions and emails attach to the project; a status report is produced as a PDF."],"h":"Triggered when a project is created, planned or progressed. Serves PRJ-01 to PRJ-05, PRJ-07, PRJ-08, PRJ-09."},{"id":"SF-43","n":"User administration and data protection","s":["An admin invites a user and assigns role, team and visibility group.","Deactivating a user ends their sessions, prompts a transfer of owned workflows and reassigns records if chosen.","Access settings can be copied from another user.","Backups run on schedule and the last success is recorded.","A restore test is run and its result recorded against the recovery targets."],"h":"Triggered by user changes and on a backup schedule. Serves SEC-09, SEC-10."},{"id":"SF-44","n":"Mobile client","s":["The app signs in and loads the focus view from the same API as the web app.","Changes arrive in real time while the app is open.","Nearby asks for location permission and queries records by distance.","A scanned business card is read on the device and shown as a contact draft for review.","Live chat takeover, project tasks and the statistics dashboard use the same endpoints as the web app."],"h":"Triggered when the mobile app opens. Serves MOB-01, MOB-02, MOB-03, MOB-08, AIA-07."},{"id":"SF-45","n":"Lead lifecycle","s":["A lead is created with its source and linked to a person or organization.","Labels and owner are set, by hand or by assignment rule.","Emails and messages on the lead are stored on it; a message from a connected channel arrives in the messaging inbox.","Converting to a deal creates the deal in the chosen pipeline and stage and moves notes, activities, emails and files.","Converting back returns the record to the leads inbox with its history.","Archiving removes the lead from the inbox without deleting it."],"h":"Triggered when a lead is created, worked or converted. Serves LEA-01, LEA-02, LEA-03, LEA-05, LEA-06."}]}

